def normalize_name(raw):
    """Collapse all whitespace to single spaces, strip, and casefold."""
    collapsed = re.sub(r"\s+", " ", raw).strip()
    return collapsed.casefold()


def parse_quantity(raw):
    """Blank quantity means 1; otherwise a nonnegative base-10 integer."""
    if raw is None:
        return 1
    text = raw.strip()
    if text == "":
        return 1
    return int(text, 10)


def main(argv):
    if len(argv) < 2:
        sys.stderr.write("usage: solution.py <input.csv>\n")
        return 2

    path = argv[1]
    totals = {}

    # Read as UTF-8, preserving input bytes exactly (read-only).
    with open(path, "r", encoding="utf-8", newline="") as fh:
        reader = csv.DictReader(fh)
        for row in reader:
            raw_item = row.get("item")
            if raw_item is None:
                continue
            name = normalize_name(raw_item)
            if not name:
                continue
            qty = parse_quantity(row.get("quantity"))
            totals[name] = totals.get(name, 0) + qty

    result = [{"item": name, "quantity": qty} for name, qty in sorted(totals.items())]

    # Preserve input bytes: emit UTF-8 characters verbatim (no \uXXXX escaping).
    sys.stdout.write(json.dumps(result, ensure_ascii=False))
    sys.stdout.write("\n")
    return 0


